	MONT_MAC(t0, t1, t2, u[0], m[1]);
	MONT_DBL(s0, s1, s2);
	MONT_ADD(t0, t1, t2, s0, s1, s2);
	u[1] = t0 * n0;
	MONT_MAC(t0, t1, t2, u[1], m[0]);
