	MONT_ADD(t0, t1, t2, w0, w1, w2);
	MONT_ADD(s0, s1, s2, c0, c1, c2);
	MONT_DBL(s0, s1, s2);
	MONT_ADD(t0, t1, t2, s0, s1, s2);
